salloc -N 1 -n <NCORES> -pgpu-h200 --gpus=1 -A<Charging account> -q<QUEUE> --mem=80G -t5:00:00
cp -r $ALPHAFOLD_ROOT/test .
cd test 

module purge
module load alphafold/2.3.2
# if you are on Phoenix cluster
export DOWNLOAD_DIR=/storage/coda1/d-pace_community/0/alphafold/alphafold_2.3.2_data
# if you are on ICE cluster 
